    int ans = 0;
    for(int i=1;i<=m;i++){
        for(int j=i;j<=m;j++){
            vector<int> num;
            int now = 0;
            for(int l=1;l<=n;l++){
                int tmp = sum[l][j]-sum[l][i-1];
                now+=tmp;
                num.push_back(now);
                if(now>=k){
                    if(ans ==0)ans=(j-i+1)*l;
                    else ans=min(ans,(j-i+1)*l);
                    int L=1,R=l;
